#include <deque>
#include <iostream>

int main() {
    std::deque<int> a = {1, 2, 3};  // First deque with elements
    std::deque<int> b = {1, 2, 4};  // Second deque for comparison
    bool result = a < b;  // Invokes operator< to compare deques
    std::cout << "Is a < b? " << (result ? "Yes" : "No") << std::endl;  // Outputs based on comparison
    return 0;
}
